mapper.sql:

JOIN tb_ai_log_issue_group_governance v ON v.issue_group_id = g.id

    AND config.environment = #{filter.environment}
    AND config.system_code = #{filter.systemCode}
    AND config.module_code = #{filter.moduleCode}

        AND (v.owner_user_id IS NULL OR v.owner_user_id = #{filter.workbenchUserId})

    AND v.owner_user_id = #{filter.ownerUserId}
    AND v.problem_type = #{filter.problemType}
    AND v.problem_level = #{filter.problemLevel}
    AND v.review_status = #{filter.reviewStatus}
    AND v.process_status = #{filter.processStatus}
    AND v.reviewer_user_id = #{filter.reviewerUserId}

        AND EXISTS (
            SELECT 1 FROM tb_ai_log_error_event e
            WHERE e.issue_group_id = g.id
            AND e.log_date >= #{filter.startLogDate}
            AND e.log_date <= #{filter.endLogDate}
        )


        AND EXISTS (
            SELECT 1 FROM tb_ai_log_ai_task_item i
            WHERE i.id = g.current_ai_item_id AND i.status = 'SUCCESS'
              AND (LOCATE(#{filter.keyword}, i.result_title) > 0
                   OR LOCATE(#{filter.keyword}, i.result_summary) > 0)
        )

mapper.select:
SELECT g.*

ORDER BY g.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM tb_ai_log_issue_group_governance
WHERE issue_group_id IN
#{id}
